-- FamVaya: Mikro-Abenteuer, Batch 1 (30 neue Einträge, alle als ENTWURF).
--
-- Im Supabase SQL Editor (Produktion) ausführen. Idempotent: bereits
-- vorhandene Slugs werden übersprungen (on conflict (slug) do nothing).
-- Kategorien werden per Slug nachgeschlagen (natur-wald, wasser-strand,
-- kreativ-entdecken); fehlt eine, bleibt category_id leer (kann im Admin
-- nachgetragen werden). Titelbild, family_rating und "persönlich getestet"
-- bewusst leer — bitte nach dem Gegenlesen im Admin pflegen und freischalten.

insert into micro_adventures (
  title, slug, short_description, full_description, category_id,
  duration_min, duration_max, cost_level, estimated_total_cost, preparation_level, difficulty_level,
  indoor, outdoor, seasonal_tags, weather_tags, materials,
  instructions, safety_notes, pros, cons,
  location_optional, status, featured
) values
  ('Spurensuche im Wald', 'spurensuche-im-wald', 'Wie Detektive nach Tierspuren, Fraßresten und Federn suchen – und rätseln, wer sie hinterlassen hat.', 'Im Wald hinterlassen Tiere überall kleine Hinweise: abgenagte Tannenzapfen, Federn, Trittsiegel im weichen Boden, angeknabberte Haselnüsse. Gemeinsam sucht ihr diese Spuren, fotografiert sie und überlegt, welches Tier dahinterstecken könnte. Das schult den Blick für Details und funktioniert mit Kindern jeden Alters, weil schon das Finden Spaß macht.', (select id from categories where content_type = 'micro_adventure' and slug = 'natur-wald'), 45, 90, 'free', 0.00, 'none', 'easy', false, true, array['fruehling', 'sommer', 'herbst', 'winter']::text[], array['trocken']::text[], array['Smartphone oder Kamera', 'kleines Notizbuch', 'festes Schuhwerk']::text[], '1. Vor dem Start gemeinsam festlegen: Wir sammeln nur Fotos und Beobachtungen, nichts wird mitgenommen.
2. Auf weichem Boden, an Wegrändern und am Bachufer nach Trittsiegeln suchen.
3. Auf abgenagte Zapfen, angeknabberte Nüsse und Federn achten und jeden Fund fotografieren.
4. Zuhause oder auf einer Bank rätseln: Wer war das? Mit einem Bestimmungsbuch oder einer Tier-App vergleichen.', 'Fundstücke wie Federn oder Knochen nicht mit bloßen Händen aufheben und danach Hände waschen. Nach dem Waldbesuch auf Zecken absuchen.', array['Funktioniert ohne Vorbereitung und ohne Kosten', 'Trainiert genaues Hinsehen bei allen Altersgruppen', 'Gut mit mehreren Kindern: Jedes sucht für sich und zeigt dann seine Funde']::text[], array['Ob und welche Spuren ihr findet, hängt von Jahreszeit und Wald ab', 'Bei nassem Wetter sind Trittsiegel besser sichtbar, aber der Boden rutschig']::text[], true, 'draft', false),
  ('Blätter-Bestimmungsrallye', 'blaetter-bestimmungsrallye', 'Wer findet die meisten verschiedenen Blätter und kann sie dem richtigen Baum zuordnen?', 'Jedes Kind bekommt eine kleine Liste mit Blattformen: gelappt, gezackt, nadelförmig, herzförmig. Gemeinsam geht ihr durch Park oder Wald, sammelt je ein heruntergefallenes Blatt pro Form und versucht, den Baum dazu zu benennen. Am Ende wird verglichen und gemeinsam bestimmt, zum Beispiel mit einer Bestimmungs-App oder einem Naturführer.', (select id from categories where content_type = 'micro_adventure' and slug = 'natur-wald'), 45, 75, 'free', 0.00, 'light', 'easy', false, true, array['fruehling', 'sommer', 'herbst']::text[], array['trocken', 'bewoelkt']::text[], array['Papier und Stifte für die Liste', 'Tüte oder Korb', 'Bestimmungsbuch oder App (optional)']::text[], '1. Eine einfache Liste mit Blattformen zeichnen oder ausdrucken.
2. Nur heruntergefallene Blätter sammeln, keine vom Baum abreißen.
3. Funde nebeneinander auslegen und die Baumart zu bestimmen versuchen.
4. Die schönsten Blätter zwischen Buchseiten pressen und später ein Blätterbild kleben.', 'Keine Blätter oder Früchte in den Mund nehmen. Einige Gehölze sind giftig. Nach dem Sammeln Hände waschen.', array['Verbindet Bewegung mit Lernen', 'Das Ergebnis lässt sich als Bastelprojekt weiterverwenden', 'Teams oder Einzelwertung lassen sich leicht an die Gruppengröße anpassen']::text[], array['Im Winter und Frühjahr gibt es kaum Laub zum Sammeln', 'Für jüngere Kinder braucht es Hilfe beim Bestimmen']::text[], true, 'draft', false),
  ('Tipi aus Totholz bauen', 'tipi-aus-totholz-bauen', 'Aus herumliegenden Ästen ein Tipi errichten und darin eine Pause machen.', 'Aus Totholz, das ohnehin am Boden liegt, baut ihr gemeinsam ein kleines Tipi. Ein stabiler Ast als Mitte, dazu Äste im Kreis angelehnt, Zweige und Laub als Wand. Das Projekt fordert Teamarbeit, Planung und Geschick, und die Kinder dürfen selbst entscheiden, wie groß und stabil es werden soll.', (select id from categories where content_type = 'micro_adventure' and slug = 'natur-wald'), 60, 120, 'free', 0.00, 'none', 'medium', false, true, array['fruehling', 'sommer', 'herbst']::text[], array['trocken']::text[], array['Totholz vom Boden', 'Arbeitshandschuhe', 'Schnur (optional)']::text[], '1. Einen ebenen, geeigneten Platz suchen, möglichst abseits von Wegen.
2. Drei bis vier lange Äste oben zusammenlehnen und mit Schnur sichern.
3. Weitere Äste im Kreis anlehnen, Lücken mit Zweigen und Laub füllen.
4. Nach dem Spielen das Tipi wieder auseinandernehmen und das Holz verteilen.', 'Nur Totholz vom Boden verwenden, keine lebenden Äste abbrechen. Auf Splitter und lose Äste achten. In Schutzgebieten und auf fremdem Grund nicht bauen, in manchen Bundesländern sind feste Bauwerke im Wald verboten.', array['Fördert Teamarbeit und Planen', 'Kostet nichts und fordert Kreativität', 'Gut für größere Kindergruppen, jeder hat eine Aufgabe']::text[], array['Rückbau gehört dazu und sollte fest eingeplant werden', 'Je nach Bundesland und Wald sind Bauwerke nicht erlaubt']::text[], true, 'draft', false),
  ('Barfußpfad selbst bauen', 'barfusspfad-selbst-bauen', 'Aus Kisten oder Schüsseln mit verschiedenen Naturmaterialien einen eigenen Fühlpfad legen.', 'Ihr füllt flache Kisten oder Schüsseln mit unterschiedlichen Materialien wie Sand, Kieseln, Moos, Tannenzapfen, Rindenmulch oder Stoff. Barfuß geht es dann über die Stationen, am besten mit geschlossenen Augen und zur Sicherheit an der Hand eines Erwachsenen oder Geschwisterkindes. Das schärft den Tastsinn und sorgt für viel Gelächter.', (select id from categories where content_type = 'micro_adventure' and slug = 'natur-wald'), 30, 60, 'low', 5.00, 'moderate', 'easy', false, true, array['fruehling', 'sommer', 'herbst']::text[], array['trocken', 'sonnig']::text[], array['flache Kisten oder Schüsseln', 'Sand, Kieselsteine, Rindenmulch, Zapfen, Stoffreste', 'Augenbinde']::text[], '1. Material sammeln und auf Splitter, Glas und spitze Teile prüfen.
2. Kisten in einer Reihe aufstellen und befüllen.
3. Reihum barfuß durchlaufen, wer möchte mit Augenbinde.
4. Raten lassen, welches Material gerade unter den Füßen ist.', 'Alle Materialien vorher auf scharfe Gegenstände prüfen. Nur im Garten oder auf geeignetem Gelände aufbauen, Augenbinde nur mit Begleitung. Kein Gartenmaterial mit Pestiziden verwenden.', array['Sinnesförderung für alle Altersstufen', 'Material meist schon im Haushalt oder Garten vorhanden', 'Lässt sich über Wochen immer wieder neu bestücken']::text[], array['Etwas Aufbauaufwand', 'Bei Kälte oder Nässe nicht angenehm']::text[], true, 'draft', false),
  ('Krabbeltier-Safari', 'krabbeltier-safari', 'Mit Becherlupe und Neugier Insekten, Käfer und Spinnen im eigenen Garten oder Park entdecken.', 'Mit einer Becherlupe oder einem Glas mit Deckel geht ihr auf Safari durch Beet, Wiese und Totholz. Unter Steinen, an Blättern und in der Rinde findet ihr erstaunlich viele Tiere. Ihr schaut sie euch ganz genau an, zählt Beine, bestaunt Muster und lasst sie danach wieder dort frei, wo ihr sie gefunden habt.', (select id from categories where content_type = 'micro_adventure' and slug = 'natur-wald'), 30, 60, 'free', 0.00, 'none', 'easy', false, true, array['fruehling', 'sommer', 'herbst']::text[], array['trocken', 'sonnig']::text[], array['Becherlupe oder Glas', 'Notizbuch', 'Bestimmungskarte (optional)']::text[], '1. Vorab Regeln festlegen: Tiere behutsam behandeln, nichts zerdrücken.
2. Unter Blättern, Steinen und in Totholz nach Tieren suchen.
3. Funde kurz in der Becherlupe betrachten und beschreiben.
4. Tiere dort freilassen, wo sie gefunden wurden, und Steine wieder zurücklegen.', 'Giftige Tiere wie Wespen, Hornissen und Zecken nicht anfassen. Allergien beachten, Tiere nur kurz festhalten. Danach auf Zecken absuchen.', array['Kinder lernen respektvollen Umgang mit Tieren', 'Funktioniert im Garten oder in der Stadt', 'Keine Vorbereitung nötig']::text[], array['Je nach Wetter und Jahreszeit sind wenige Tiere unterwegs', 'Mit Insektenangst nicht für alle geeignet']::text[], true, 'draft', false),
  ('Pilze fotografieren statt sammeln', 'pilze-fotografieren', 'Auf Pilzsafari gehen und die Funde ausschließlich mit der Kamera sammeln.', 'Im Herbst zeigen sich im Wald überraschend viele Formen und Farben von Pilzen. Statt sie zu pflücken, fotografiert ihr sie aus verschiedenen Blickwinkeln, vergleicht sie später mit einem Pilzführer oder einer Bestimmungs-App und erstellt ein eigenes Pilz-Album. So bleibt der Wald unberührt und niemand kommt mit giftigen Arten in Kontakt.', (select id from categories where content_type = 'micro_adventure' and slug = 'natur-wald'), 45, 90, 'free', 0.00, 'none', 'easy', false, true, array['herbst']::text[], array['trocken', 'bewoelkt']::text[], array['Smartphone oder Kamera', 'Pilzführer oder App (optional)']::text[], '1. Im Wald langsam gehen und gezielt auf Baumstümpfen, Moos und Wegrändern suchen.
2. Jeden Pilz von oben, von der Seite und die Unterseite fotografieren, ohne ihn zu berühren.
3. Fund-Ort und Größe notieren, zum Beispiel mit einem Fuß oder Stift als Maßstab.
4. Zuhause ein Album oder eine Collage mit den schönsten Funden gestalten.', 'Pilze niemals essen und nicht in den Mund nehmen. Auch Berührung nur mit Vorsicht, anschließend Hände waschen. Pilze nicht zertreten oder abreißen.', array['Schonend für den Wald', 'Fördert genaues Beobachten und Dokumentieren', 'Eignet sich auch für kleinere Kinder, wenn sie nicht anfassen dürfen']::text[], array['Ergebnis hängt stark von Jahreszeit und Wetter ab', 'Sicheres Bestimmen ist schwierig, die Bestimmung ersetzt keine Pilzberatung']::text[], true, 'draft', false),
  ('Geocaching für Anfänger', 'geocaching-fuer-anfaenger', 'Mit dem Smartphone auf Schatzsuche gehen und einen Cache in der Nähe finden.', 'Geocaching ist eine weltweite Schatzsuche: Versteckte Behälter, sogenannte Caches, werden anhand von GPS-Koordinaten gesucht. Für den Einstieg eignen sich einfache, traditionelle Caches mit niedriger Schwierigkeit in der Nähe. Ihr tragt euch ins Logbuch ein, tauscht vielleicht ein kleines Fundstück und versteckt alles wieder exakt so, wie ihr es vorgefunden habt.', (select id from categories where content_type = 'micro_adventure' and slug = 'natur-wald'), 60, 120, 'free', 0.00, 'light', 'medium', false, true, array['fruehling', 'sommer', 'herbst']::text[], array['trocken']::text[], array['Smartphone mit Geocaching-App', 'Stift fürs Logbuch', 'kleines Tauschgeschenk (optional)']::text[], '1. App herunterladen und einen Anfänger-Cache in Wohnortnähe auswählen (Schwierigkeit und Gelände niedrig).
2. Gemeinsam zur Position navigieren und aufmerksam in der Umgebung suchen.
3. Cache vorsichtig öffnen, ins Logbuch eintragen und alles wieder sorgfältig verschließen.
4. Den Behälter exakt am gleichen Platz zurücklegen und den Fund in der App loggen.', 'Nur Caches an erlaubten, gut zugänglichen Orten suchen und nicht auf Privatgrund, Gleisen oder in Schutzgebieten abseits der Wege. Kinder nicht an Straßen oder Gewässern unbeaufsichtigt lassen.', array['Bewegung und Rätselspaß kombiniert', 'Fast überall verfügbar', 'Passt gut für gemischte Altersgruppen']::text[], array['Braucht Smartphone mit Datenverbindung und Akku', 'Die App bietet kostenpflichtige Zusatzfunktionen, die Basisfunktionen reichen aber']::text[], true, 'draft', false),
  ('Blinde Karawane im Wald', 'blinde-karawane', 'Mit verbundenen Augen von einem Geschwisterkind durch den Wald geführt werden und dabei alle Sinne schärfen.', 'Ein Kind trägt eine Augenbinde, ein anderes führt es sicher an der Hand oder an der Schulter über einen ebenen Waldweg. Ihr wechselt die Rollen. Wer nichts sieht, hört, riecht und fühlt viel intensiver: Vogelstimmen, Laub unter den Füßen, den Duft von Harz. Die Aktivität stärkt Vertrauen und Verantwortung zwischen den Kindern.', (select id from categories where content_type = 'micro_adventure' and slug = 'natur-wald'), 30, 60, 'free', 0.00, 'none', 'easy', false, true, array['fruehling', 'sommer', 'herbst']::text[], array['trocken']::text[], array['Augenbinde oder Schal']::text[], '1. Einen ebenen, übersichtlichen Weg ohne Gefälle auswählen.
2. Eine Person verbindet sich die Augen, die andere führt langsam und kündigt Hindernisse an.
3. Mitten auf dem Weg anhalten und gemeinsam benennen: Was hörst du, was riechst du?
4. Rollen tauschen und anschließend über die Eindrücke sprechen.', 'Nur auf ebenen Wegen, fern von Hängen, Gewässern und Straßen. Führende Person muss immer in Berührung bleiben. Wer sich unwohl fühlt, nimmt die Binde sofort ab.', array['Stärkt Vertrauen und Rücksicht unter Geschwistern', 'Ohne Material und fast ohne Vorbereitung', 'Wirkt auf Kinder jeden Alters']::text[], array['Nicht jedes Kind mag verbundene Augen', 'Braucht aufmerksame Aufsicht']::text[], true, 'draft', false),
  ('Stockbrot am Grillplatz', 'stockbrot-am-grillplatz', 'Teig auf einen Stock wickeln und über der Glut backen – nur an dafür vorgesehenen Feuerstellen.', 'Stockbrot gehört für viele Kinder zu den schönsten Outdoor-Erlebnissen. Ihr bereitet den Hefeteig zuhause vor oder nutzt fertigen Teig, wickelt ihn um saubere Stöcke und backt ihn über der Glut an einer offiziellen Grill- oder Feuerstelle. Dabei lernen Kinder, wie man ruhig am Feuer sitzt und geduldig wartet.', (select id from categories where content_type = 'micro_adventure' and slug = 'natur-wald'), 60, 120, 'low', 8.00, 'moderate', 'medium', false, true, array['fruehling', 'sommer', 'herbst']::text[], array['trocken', 'windstill']::text[], array['Hefeteig oder fertiger Brotteig', 'Haselnuss- oder Weidenstöcke', 'Wasser zum Löschen', 'Grillhandschuhe']::text[], '1. Offizielle Grill- oder Feuerstelle suchen und zuvor klären, ob Feuer aktuell erlaubt ist.
2. Stöcke schälen und glatt machen, Teig dünn um das Stockende wickeln.
3. Teig langsam und mit Abstand zur Flamme über der Glut drehen, bis er goldbraun ist.
4. Feuer vollständig ablöschen und die Feuerstelle sauber hinterlassen.', 'Kinder nie allein am Feuer lassen. Nur bei erlaubter Feuerstelle, keine Feuer bei Waldbrandgefahr oder Feuerverbot. Eimer Wasser bereitstellen, Haare zusammenbinden, auf Abstand achten.', array['Echtes Naturerlebnis, das lange in Erinnerung bleibt', 'Teig lässt sich einfach vorbereiten', 'Skaliert gut auf mehrere Kinder']::text[], array['Braucht erlaubte Feuerstelle und passendes Wetter', 'Beim Feuer ist ständige Aufsicht nötig']::text[], true, 'draft', false),
  ('Nachtspaziergang mit Taschenlampe', 'nachtspaziergang-mit-taschenlampe', 'Den vertrauten Weg im Dunkeln neu entdecken und auf nächtliche Geräusche lauschen.', 'Bei Einbruch der Dunkelheit macht ihr einen kurzen Spaziergang auf einem bekannten Weg. Mit Taschenlampen und Stirnlampen sieht plötzlich alles anders aus: Schatten wachsen, Geräusche werden lauter. Ihr bleibt stehen, schaltet die Lampen aus und lauscht, was ihr hört. Das Erlebnis ist aufregend und gleichzeitig beruhigend.', (select id from categories where content_type = 'micro_adventure' and slug = 'natur-wald'), 30, 60, 'free', 0.00, 'light', 'easy', false, true, array['herbst', 'winter', 'fruehling']::text[], array['trocken', 'klar']::text[], array['Taschenlampen oder Stirnlampen', 'reflektierende Kleidung', 'warme Jacken']::text[], '1. Einen sicheren, bekannten Weg mit wenig Verkehr auswählen.
2. Alle bekommen eine Lampe oder tragen reflektierende Kleidung.
3. An einer ruhigen Stelle alle Lichter ausschalten, zwei Minuten lauschen und danach erzählen, was man gehört hat.
4. Den Rückweg gemeinsam im Licht zurücklegen.', 'Nur auf sicheren Wegen ohne Verkehr, zusammenbleiben. Nicht in der Nähe von Gewässern oder Waldrändern, wo Wild unterwegs sein kann. Für kleinere Kinder die Dauer kurz halten.', array['Intensives Erlebnis ohne Aufwand', 'Gut für Kinder, die tagsüber schon alles kennen', 'Funktioniert auch im Winter und in der Stadt']::text[], array['Für ängstliche Kinder zunächst ungewohnt', 'Nicht bei Regen oder Glätte geeignet']::text[], true, 'draft', false),
  ('Klangkarte erstellen', 'klangkarte-erstellen', 'Auf einem ruhigen Platz die Augen schließen, alle Geräusche aufschreiben oder zeichnen und daraus eine Karte machen.', 'Ihr setzt euch an einen ruhigen Platz im Park, Garten oder Wald und schließt für zwei bis drei Minuten die Augen. Danach zeichnet ihr einen Kreis in euer Notizbuch, markiert euren Standort in der Mitte und tragt ein, aus welcher Richtung welche Geräusche kommen. Zusammen entsteht eine kleine Klanglandschaft, die ihr später vergleichen könnt.', (select id from categories where content_type = 'micro_adventure' and slug = 'natur-wald'), 20, 45, 'free', 0.00, 'none', 'easy', false, true, array['fruehling', 'sommer', 'herbst', 'winter']::text[], array['trocken', 'bewoelkt']::text[], array['Papier und Stifte', 'Klemmbrett oder feste Unterlage']::text[], '1. Einen Platz wählen, an dem ihr ungestört sitzen könnt.
2. Zwei Minuten still sein und die Augen schließen.
3. Auf Papier einen Kreis zeichnen, die Mitte ist euer Platz. Geräusche je nach Richtung als Symbol oder Wort eintragen.
4. Karten untereinander vergleichen und besprechen, wer was gehört hat.', 'Platz mit Abstand zu Straßen und Gewässern wählen, damit die Kinder mit geschlossenen Augen sicher sitzen.', array['Beruhigt und sammelt Aufmerksamkeit', 'Gut für den Alltag und für unterwegs', 'Mit jeder Gruppengröße machbar']::text[], array['Jüngere Kinder halten die Stille nur kurz aus', 'Wenig körperliche Bewegung']::text[], true, 'draft', false),
  ('Steine flitschen – Familienmeisterschaft', 'steine-flitschen', 'Am See oder ruhigen Fluss die flachsten Steine suchen und zählen, wie oft sie hüpfen.', 'Flache, glatte Steine werden mit seitlichem Wurf über ruhiges Wasser geschleudert. Wer zählt die meisten Hüpfer? Zuerst suchen die Kinder passende Steine, üben die Wurftechnik und führen dann eine kleine Meisterschaft durch. Das funktioniert an Seen und ruhigen Flüssen und bringt auch Erwachsene ins Schwitzen.', (select id from categories where content_type = 'micro_adventure' and slug = 'wasser-strand'), 30, 60, 'free', 0.00, 'none', 'medium', false, true, array['fruehling', 'sommer', 'herbst']::text[], array['trocken', 'windstill']::text[], array['flache Steine', 'Notizblock für die Punkte']::text[], '1. Ruhige Stelle am Ufer wählen, an der niemand badet oder paddelt.
2. Gemeinsam flache, handtellergroße Steine sammeln.
3. Seitlich aus dem Handgelenk werfen und die Hüpfer laut zählen.
4. Jede Runde drei Würfe, höchste Hüpfzahl gewinnt.', 'Nur werfen, wenn keine Personen im Wasser oder in Wurfrichtung sind. Abstand zu anderen Gästen halten und Kinder am Ufer nicht unbeaufsichtigt lassen.', array['Kostenlos und schnell gestartet', 'Einfaches Regelwerk, auch für größere Gruppen', 'Passt gut als Zwischenstopp bei Ausflügen']::text[], array['Braucht ruhiges Wasser und geeignete Steine', 'Technik muss geübt werden']::text[], true, 'draft', false),
  ('Wasserrad aus Naturmaterial', 'wasserrad-aus-naturmaterial', 'Mit Ästen, Blättern und einem Stock ein kleines Wasserrad im flachen Bach bauen.', 'Aus einem geraden Ast als Achse, Rinde oder Blättern als Schaufeln und zwei Astgabeln als Halterung bauen die Kinder ein kleines Wasserrad. Am flachen Bach wird es getestet. Dreht es sich nicht, wird nachgebessert. So lernen Kinder spielerisch, wie Wasserkraft funktioniert.', (select id from categories where content_type = 'micro_adventure' and slug = 'wasser-strand'), 45, 90, 'free', 0.00, 'light', 'medium', false, true, array['fruehling', 'sommer', 'herbst']::text[], array['trocken', 'sonnig']::text[], array['gerader Ast', 'zwei Astgabeln', 'Rinde oder große Blätter', 'Schnur oder Gummiband']::text[], '1. Einen flachen, ruhigen Bach mit leichter Strömung suchen.
2. Aus Rinde oder Blättern vier bis sechs Schaufeln schneiden oder falten.
3. Schaufeln an die Achse binden und die Achse in zwei Astgabeln lagern.
4. Im Wasser testen und das Rad verbessern, bis es sich dreht.', 'Nur an flachen Bachstellen spielen, Rutschgefahr auf Steinen. Wasser vor dem Spielen auf Strömung prüfen und bei Regen oder Hochwasser nicht ins Wasser gehen.', array['Verbindet Basteln mit Physik', 'Mit Material aus der Natur', 'Mehrere Kinder können verschiedene Konstruktionen bauen']::text[], array['Braucht einen geeigneten Bach', 'Je nach Material etwas Geduld nötig']::text[], true, 'draft', false),
  ('Mini-Staudamm im flachen Bach', 'mini-staudamm', 'Mit Steinen und Ästen an einer geeigneten Bachstelle einen kleinen Damm bauen und danach wieder abbauen.', 'An einer flachen Stelle eines naturnahen Bachs bauen die Kinder aus Steinen, Ästen und Schlamm einen Mini-Staudamm. Dabei erleben sie, wie Wasser sich staut und seinen Weg sucht. Ganz wichtig: Alles wird nach dem Spiel wieder zurückgebaut, damit der Bach frei fließen kann.', (select id from categories where content_type = 'micro_adventure' and slug = 'wasser-strand'), 45, 90, 'free', 0.00, 'none', 'medium', false, true, array['sommer', 'fruehling']::text[], array['trocken', 'sonnig']::text[], array['Gummistiefel oder Wasserschuhe', 'Handtücher', 'Wechselkleidung']::text[], '1. Einen kleinen, flachen Bach wählen und prüfen, ob Spielen erlaubt ist.
2. Steine und Äste sammeln und als Mauer in den Bach legen.
3. Beobachten, wie sich das Wasser staut und wo es überläuft.
4. Alles wieder zurückbauen, Steine zurücklegen und den Bach wie vorgefunden verlassen.', 'Nur bei niedrigem Wasserstand, nie bei Regen oder nach Hochwasser. Nicht in Schutzgebieten bauen, Tierleben nicht stören. Auf Rutschgefahr achten.', array['Intensive Naturerfahrung', 'Beschäftigt mehrere Kinder lange', 'Fördert Planen und Teamarbeit']::text[], array['Nasse Kleidung ist garantiert', 'Nicht an jedem Bach erlaubt, vorher klären']::text[], true, 'draft', false),
  ('Strandolympiade', 'strandolympiade', 'Ein Tag am See oder Meer wird zur Olympiade mit Sandburg-Weitwurf, Muschelsammeln und Wettrennen.', 'Ihr denkt euch fünf bis sechs Disziplinen aus, die am Strand oder Seeufer funktionieren: Sandburg bauen, Muschelsammeln, Weitwurf mit Sandbällen, Wettlauf im Sand, Flaggenlauf. Alle sammeln Punkte, am Ende gibt es eine Siegerehrung mit selbstgebastelten Medaillen. Das Format eignet sich bestens für Familien mit mehreren Kindern, weil Teams gebildet werden können.', (select id from categories where content_type = 'micro_adventure' and slug = 'wasser-strand'), 60, 120, 'free', 0.00, 'light', 'easy', false, true, array['sommer']::text[], array['sonnig', 'trocken']::text[], array['Eimer und Schaufeln', 'Stoppuhr oder Smartphone', 'Pappe für Medaillen (optional)']::text[], '1. Gemeinsam fünf bis sechs Disziplinen festlegen und kurz erklären.
2. Teams bilden und die Reihenfolge abstimmen.
3. Punkte auf einem Zettel oder im Sand notieren.
4. Siegerehrung mit Medaillen oder einer kleinen Belohnung am Ende.', 'Sonnenschutz, ausreichend Wasser zum Trinken. Baden nur mit Aufsicht und an bewachten Stellen. Nicht in der Mittagshitze durchführen.', array['Gut für mehrere Kinder und gemischte Altersgruppen', 'Keine besonderen Materialien nötig', 'Verbindet Bewegung, Teamgeist und Kreativität']::text[], array['Nur bei gutem Wetter und am Wasser möglich', 'Braucht ein wenig Organisation vorab']::text[], true, 'draft', false),
  ('Schwammbomben-Schlacht', 'schwammbomben-schlacht', 'Eine Wasserschlacht mit Schwämmen statt Ballons – wiederverwendbar und ohne Plastikmüll.', 'Alte Schwämme oder Putztücher werden in Eimern mit Wasser getränkt und als Wurfgeschosse benutzt. Damit lässt sich eine Wasserschlacht veranstalten, die ohne zerplatzte Plastikreste auskommt. Teams stehen sich gegenüber oder jeder gegen jeden. Perfekt für heiße Sommertage und den Garten.', (select id from categories where content_type = 'micro_adventure' and slug = 'wasser-strand'), 30, 60, 'low', 3.00, 'light', 'easy', false, true, array['sommer']::text[], array['sonnig', 'trocken']::text[], array['Schwämme oder Putztücher', 'Eimer mit Wasser', 'Badekleidung', 'Handtücher']::text[], '1. Eimer mit Wasser füllen und Schwämme bereitlegen.
2. Teams bilden und Spielfeld mit klaren Grenzen markieren.
3. Schwämme eintauchen und mit Schwung auf das andere Team werfen.
4. Nach dem Spiel Schwämme ausspülen und trocknen lassen.', 'Nur auf rutschfestem Untergrund spielen. Gesicht nicht gezielt treffen. Sonnenschutz und Trinkpausen einplanen. Wasser sparsam einsetzen, besonders in Trockenzeiten.', array['Günstig und wiederverwendbar', 'Hoher Spaßfaktor bei mehreren Kindern', 'Kaum Vorbereitung nötig']::text[], array['Nur bei warmem Wetter sinnvoll', 'Wasserverbrauch im Garten bedenken']::text[], true, 'draft', false),
  ('Eisskulpturen im Frost', 'eisskulpturen-im-frost', 'Bei Frost Wasser in Förmchen gefrieren lassen, mit Salz und Farbe zu Eisskulpturen verzaubern.', 'An frostigen Tagen füllt ihr Förmchen, Schüsseln oder Eimer mit Wasser, gebt Naturmaterialien wie Beeren, Zweige oder Blüten hinein und lasst alles über Nacht draußen gefrieren. Am nächsten Tag stürzt ihr die Eisformen, hängt sie auf oder baut Skulpturen. Mit Salz und Lebensmittelfarbe lassen sich spannende Experimente machen.', (select id from categories where content_type = 'micro_adventure' and slug = 'wasser-strand'), 30, 60, 'free', 0.00, 'light', 'easy', false, true, array['winter']::text[], array['frost']::text[], array['Förmchen oder Schüsseln', 'Wasser', 'Naturmaterialien', 'Salz und Lebensmittelfarbe (optional)', 'Schnur zum Aufhängen']::text[], '1. Formen mit Wasser füllen, Naturmaterial hineinlegen und eine Schnurschlaufe einlegen.
2. Über Nacht bei Frost draußen stehen lassen.
3. Eis aus den Formen lösen und im Garten aufhängen oder zu Skulpturen stapeln.
4. Mit Salz experimentieren: Das Eis schmilzt an der Stelle, Farbe sammelt sich in den Rillen.', 'Salz und Farbe nicht in die Augen oder den Mund bringen, Handschuhe tragen. Eis nicht ablecken, Erfrierungen vermeiden und Hände zwischendurch aufwärmen.', array['Verbindet Basteln und Experimentieren', 'Verlängert die Outdoor-Saison bis in den Winter', 'Ergebnis hält mehrere Tage']::text[], array['Braucht anhaltenden Frost', 'In milden Wintern nicht möglich']::text[], true, 'draft', false),
  ('Schneeburg-Bauwerkstatt', 'schneeburg-bauwerkstatt', 'Mit Eimern und Schaufeln eine kleine Burg oder Mauer aus Schnee bauen.', 'Wenn Schnee liegt, bauen die Kinder mit Eimern, Förmchen und Schaufeln Schneeziegel und errichten daraus eine Burgmauer oder ein kleines Fort. Die Aufgaben lassen sich gut verteilen: Ziegelhersteller, Baumeister, Fahnenbauer. Zum Schluss bekommt die Burg Fenster, Zinnen und eine Fahne.', (select id from categories where content_type = 'micro_adventure' and slug = 'wasser-strand'), 45, 120, 'free', 0.00, 'none', 'easy', false, true, array['winter']::text[], array['schnee']::text[], array['Eimer und Förmchen', 'Schaufeln', 'wasserfeste Kleidung', 'warme Handschuhe']::text[], '1. Feuchten, formbaren Schnee suchen, am besten bei Temperaturen um 0 Grad.
2. Schnee in Eimer füllen, festdrücken und als Ziegel stürzen.
3. Ziegel reihenweise zu einer Mauer aufschichten und mit Schnee verfugen.
4. Mit Fahne, Fenstern und Zinnen verzieren.', 'Keine tiefen Höhlen oder Tunnel graben, Einsturzgefahr. Burg nur so hoch bauen, dass sie niemanden gefährdet. Auf Aufwärmpausen und trockene Kleidung achten.', array['Kostenlos und für alle Altersstufen', 'Teamarbeit mit klaren Aufgaben für mehrere Kinder', 'Bleibt als Spielort noch Tage stehen']::text[], array['Nur bei Schnee möglich', 'Pulverschnee eignet sich nicht zum Bauen']::text[], true, 'draft', false),
  ('Schatzsuche mit selbstgemalter Karte', 'schatzsuche-mit-selbstgemalter-karte', 'Eine Schatzkarte zeichnen, altern lassen und gemeinsam im Garten oder Park einen Schatz suchen.', 'Ein Elternteil oder ein älteres Kind versteckt einen kleinen Schatz und zeichnet eine Karte mit Hinweisen. Die Karte wird mit kaltem Tee leicht gefärbt, damit sie alt aussieht, und die Suche kann beginnen. Mehrere Kinder können gemeinsam suchen oder in Teams gegeneinander antreten. Der Schatz kann aus Süßigkeiten, kleinen Spielzeugen oder Gutscheinen bestehen.', (select id from categories where content_type = 'micro_adventure' and slug = 'kreativ-entdecken'), 45, 90, 'low', 5.00, 'moderate', 'easy', false, true, array['fruehling', 'sommer', 'herbst']::text[], array['trocken']::text[], array['Papier und Stifte', 'kalter Tee zum Färben', 'kleine Schatzkiste', 'Kleinigkeiten als Schatz']::text[], '1. Schatz verstecken und Weg mit drei bis fünf Stationen planen.
2. Karte zeichnen und Hinweise oder Rätsel für jede Station schreiben.
3. Papier kurz in kalten Tee tauchen und trocknen lassen.
4. Suche starten und am Ziel den Schatz gemeinsam öffnen.', 'Keine Verstecke an gefährlichen Stellen wie Hängen oder Gewässern wählen. Kleinteile nur für Kinder ab drei Jahren verwenden.', array['Beschäftigt mehrere Kinder und Altersstufen zugleich', 'Lässt sich beliebig anpassen: Garten, Park oder Wohnung', 'Verbindet Kreativität mit Bewegung']::text[], array['Vorbereitung durch einen Erwachsenen nötig', 'Rätsel müssen zum Alter der Kinder passen']::text[], true, 'draft', false),
  ('Familien-Zeitkapsel vergraben', 'familien-zeitkapsel', 'Erinnerungen, Zeichnungen und Wünsche in einer Dose verstecken und in einem Jahr wieder ausgraben.', 'Jedes Familienmitglied legt etwas in eine wasserdichte Dose: eine Zeichnung, ein Foto, einen Brief an sein zukünftiges Ich oder einen Lieblingsgegenstand. Die Dose wird vergraben, der Ort markiert, und nach einem Jahr feierlich wieder geöffnet. Das Projekt macht deutlich, wie sehr sich Kinder und Interessen verändern.', (select id from categories where content_type = 'micro_adventure' and slug = 'kreativ-entdecken'), 45, 90, 'low', 5.00, 'light', 'easy', false, true, array['fruehling', 'sommer', 'herbst']::text[], array['trocken']::text[], array['wasserdichte Dose oder Box', 'Papier und Stifte', 'Fotos und Erinnerungsstücke', 'kleine Schaufel']::text[], '1. Dose auswählen und jedes Familienmitglied bitten, etwas hineinzulegen.
2. Briefe an das zukünftige Ich schreiben oder malen.
3. Dose im eigenen Garten vergraben und Platz mit Foto und Skizze markieren.
4. Termin für die Ausgrabung in einem Jahr in den Kalender eintragen.', 'Nur auf eigenem Grundstück oder mit Erlaubnis vergraben, vorher auf Leitungen achten. Keine Lebensmittel oder verderblichen Dinge einlegen.', array['Bleibt als gemeinsame Erinnerung lange wirksam', 'Kinder jeden Alters können sich beteiligen', 'Kostet fast nichts']::text[], array['Auf das Wiederausgraben muss man ein Jahr warten', 'Braucht passenden Platz, am besten im eigenen Garten']::text[], true, 'draft', false),
  ('Naturfarben herstellen und malen', 'naturfarben-herstellen', 'Aus Rote Bete, Kurkuma, Spinat und Blaukraut eigene Farben anrühren und damit malen.', 'Aus Lebensmitteln lassen sich kräftige Farben gewinnen: Rote Bete ergibt Rot-Rosa, Kurkuma Gelb, Spinat Grün, Rotkohl Violett bis Blau. Ihr kocht kleine Mengen ein, lasst die Farben abkühlen und malt damit auf dickem Papier. Ein Spritzer Zitrone oder Natron verändert beim Rotkohl die Farbe, was Kinder begeistert.', (select id from categories where content_type = 'micro_adventure' and slug = 'kreativ-entdecken'), 45, 90, 'low', 8.00, 'moderate', 'medium', true, false, array['fruehling', 'sommer', 'herbst', 'winter']::text[], array['regen', 'trocken']::text[], array['Rote Bete, Kurkuma, Spinat, Rotkohl', 'kleine Töpfe und Schälchen', 'Pinsel', 'dickes Zeichenpapier', 'Malkittel']::text[], '1. Gemüse klein schneiden und je in einem Topf mit wenig Wasser kurz aufkochen.
2. Sud abseihen, abkühlen lassen und in Schälchen füllen.
3. Mit Pinsel auf dickem Papier malen und trocknen lassen.
4. Beim Rotkohl-Sud einen Spritzer Zitronensaft oder eine Prise Natron probieren und die Farbänderung beobachten.', 'Kochen und Umgang mit heißem Sud nur durch Erwachsene. Tischdecke und Malkittel nutzen, Farben können Kleidung färben. Nur Lebensmittel verwenden, keine Zusätze.', array['Lehrreich und zugleich kreativ', 'Farben stammen aus der Küche', 'Gut für Regentage und für mehrere Kinder am Tisch']::text[], array['Farben sind nicht lichtecht und verblassen mit der Zeit', 'Kochen und Aufräumen erfordern Zeit']::text[], true, 'draft', false),
  ('Schattentheater mit Taschenlampe', 'schattentheater', 'Mit einem Bettlaken, einer Lampe und Pappfiguren eine eigene Vorstellung aufführen.', 'Ein Bettlaken wird aufgehängt oder gespannt, dahinter steht eine helle Lampe. Aus Pappe schneidet ihr Figuren und befestigt sie an Stäben. Mit den Händen lassen sich außerdem einfache Tiere formen. Die Kinder denken sich eine Geschichte aus und führen sie der Familie vor, am besten im abgedunkelten Raum.', (select id from categories where content_type = 'micro_adventure' and slug = 'kreativ-entdecken'), 45, 90, 'low', 3.00, 'moderate', 'easy', true, false, array['fruehling', 'herbst', 'winter']::text[], array['regen', 'dunkel']::text[], array['helles Bettlaken', 'Taschenlampe oder Schreibtischlampe', 'Pappe', 'Schere', 'Holzstäbe oder Strohhalme']::text[], '1. Laken zwischen zwei Stuhllehnen oder an einer Leine spannen.
2. Figuren aus Pappe schneiden und an Stäben befestigen.
3. Lampe hinter dem Laken aufstellen und Zuschauer davor setzen.
4. Geschichte erzählen und die Figuren vor der Lampe bewegen.', 'Lampe nicht zu nah am Stoff platzieren. Wärmeentwickelnde Lampen nicht direkt an das Laken lehnen. Scheren nur mit Aufsicht benutzen.', array['Ideal für Regentage', 'Alle Altersgruppen können mitmachen', 'Fördert Fantasie und Erzählen']::text[], array['Raum muss verdunkelt werden', 'Basteln der Figuren dauert etwas']::text[], true, 'draft', false),
  ('Höhlenbau im Wohnzimmer', 'hoehlenbau-im-wohnzimmer', 'Aus Decken, Stühlen und Kissen eine große Höhle bauen und dort Geschichten erzählen.', 'Aus Stühlen, Decken, Kissen und Wäscheklammern wird im Wohnzimmer eine große Höhle. Mit Lichterketten und Taschenlampen gemütlich ausgestattet, lädt sie zum Vorlesen, Hörspielhören oder Picknick ein. Mehrere Kinder können gemeinsam planen und bauen, wer will, schläft sogar dort.', (select id from categories where content_type = 'micro_adventure' and slug = 'kreativ-entdecken'), 60, 150, 'free', 0.00, 'light', 'easy', true, false, array['fruehling', 'herbst', 'winter']::text[], array['regen', 'frost', 'schnee']::text[], array['Decken und Laken', 'Stühle oder Wäscheständer', 'Kissen', 'Wäscheklammern', 'LED-Lichterkette']::text[], '1. Stühle und Möbel als Gerüst anordnen.
2. Decken darüber legen und mit Klammern fixieren.
3. Höhle mit Kissen, Matratzen und Lichterkette gemütlich einrichten.
4. Gemeinsam vorlesen, Hörspiel hören oder Snacks essen.', 'Decken nicht über Kerzen, Heizkörper oder warme Lampen legen, nur LED-Licht verwenden. Standfestigkeit prüfen, damit nichts umkippt.', array['Kostenlos und sofort umsetzbar', 'Beschäftigt mehrere Kinder lange', 'Sehr gut für Regen- und Schneetage']::text[], array['Wohnzimmer wirkt danach chaotisch', 'Aufräumen sollte fest eingeplant werden']::text[], true, 'draft', false),
  ('Pizza-Duell: Jeder belegt seine eigene', 'pizza-duell', 'Jedes Kind belegt seine eigene Mini-Pizza, am Ende gibt es eine Jury und Preise.', 'Ihr bereitet Pizzateig vor oder nehmt fertigen, stellt viele Zutaten bereit und jedes Familienmitglied gestaltet eine eigene Pizza. Nach dem Backen bewertet eine Jury nach Kategorien wie Kreativität, Optik oder Geschmack. Das funktioniert besonders gut mit mehreren Kindern, die gern selbst entscheiden.', (select id from categories where content_type = 'micro_adventure' and slug = 'kreativ-entdecken'), 75, 120, 'low', 12.00, 'moderate', 'easy', true, false, array['fruehling', 'sommer', 'herbst', 'winter']::text[], array['regen', 'trocken']::text[], array['Pizzateig', 'Tomatensauce', 'Käse und verschiedene Beläge', 'Backbleche', 'Schürzen']::text[], '1. Teig ausrollen und kleine Pizzaböden formen.
2. Zutaten in Schälchen bereitstellen, jedes Kind belegt seine Pizza.
3. Im vorgeheizten Ofen backen, Heißes nur durch Erwachsene hantieren lassen.
4. Jury-Runde mit Bewertungskategorien und kleinen Preisen durchführen.', 'Ofen und heiße Bleche nur durch Erwachsene bedienen. Allergien und Unverträglichkeiten bei den Belägen beachten. Messer nur mit Aufsicht.', array['Alle essen am Ende satt', 'Jedes Kind kann selbst entscheiden', 'Gut für Regentage und Geburtstage']::text[], array['Küche muss danach aufgeräumt werden', 'Kosten steigen mit Anzahl der Zutaten']::text[], true, 'draft', false),
  ('Mini-Olympiade im Garten', 'mini-olympiade-im-garten', 'Fünf einfache Disziplinen, Teams, Punktetafel und eine Siegerehrung – alles aus Material, das ihr schon habt.', 'Im Garten oder im Park denkt ihr euch fünf bis sechs Disziplinen aus: Sackhüpfen, Eierlauf mit Löffel, Dosenwerfen, Weitsprung, Gummistiefel-Weitwurf. Die Kinder bilden Teams, sammeln Punkte und bekommen am Ende Medaillen aus Pappe. Mit mehreren Kindern entsteht schnell Wettkampfstimmung, die Regeln lassen sich leicht an das Alter anpassen.', (select id from categories where content_type = 'micro_adventure' and slug = 'kreativ-entdecken'), 60, 120, 'free', 0.00, 'light', 'easy', false, true, array['fruehling', 'sommer', 'herbst']::text[], array['trocken', 'sonnig']::text[], array['Löffel und Bälle oder Kartoffeln', 'Kissenbezüge für Sackhüpfen', 'Dosen zum Werfen', 'Papier für Punktetafel']::text[], '1. Disziplinen sammeln und Regeln festlegen.
2. Teams mischen, damit sie ungefähr ausgeglichen sind.
3. Alle Disziplinen nacheinander spielen und Punkte eintragen.
4. Siegerehrung mit selbstgebastelten Medaillen.', 'Auf rutschfesten Untergrund achten, genug Platz zwischen den Stationen. Trinkpausen einplanen. Schwächere Teilnehmer durch angepasste Regeln unterstützen.', array['Ohne Spezialmaterial', 'Gut für große Familien und Kindergruppen', 'Bewegung und Teamgeist in einem']::text[], array['Organisation durch einen Erwachsenen sinnvoll', 'Streit um Regeln möglich, vorher klar absprechen']::text[], true, 'draft', false),
  ('Papierflieger-Wettbewerb', 'papierflieger-wettbewerb', 'Verschiedene Flugzeugmodelle falten und testen, wessen Flieger am weitesten und längsten fliegt.', 'Ihr faltet mehrere Modelle aus normalem Papier und testet sie in drei Kategorien: weitester Flug, längste Flugzeit, schönster Kunstflug. Die Kinder tüfteln selbst an Flügeln und Gewichten und beobachten, wie sich kleine Änderungen auswirken. Mit einem Maßband wird gemessen, die besten Flieger kommen ins Finale.', (select id from categories where content_type = 'micro_adventure' and slug = 'kreativ-entdecken'), 30, 60, 'free', 0.00, 'none', 'easy', true, true, array['fruehling', 'sommer', 'herbst', 'winter']::text[], array['trocken', 'regen']::text[], array['Papier', 'Maßband', 'Stoppuhr', 'Büroklammern zum Beschweren']::text[], '1. Mehrere Faltanleitungen ausprobieren oder gemeinsam erfinden.
2. Startlinie festlegen und in drei Kategorien messen.
3. Verbesserungen testen: Flügel biegen, Klammer ans Ende setzen.
4. Gewinner küren und Flugzeuge dekorieren.', 'Beim Werfen auf Mitspieler achten und in leerer Richtung starten. Drinnen auf zerbrechliche Gegenstände achten.', array['Fast ohne Kosten und Vorbereitung', 'Drinnen und draußen möglich', 'Fördert Ausprobieren und Technikverständnis']::text[], array['Windiges Wetter stört Messungen', 'Ältere Kinder wollen oft komplexere Modelle']::text[], true, 'draft', false),
  ('Familien-Podcast aufnehmen', 'familien-podcast', 'Mit dem Smartphone eine Interview- oder Geschichtensendung aufnehmen – nur für die Familie.', 'Ihr nutzt die Sprachmemo-Funktion eures Smartphones und nehmt eine kleine Familiensendung auf. Die Kinder interviewen Eltern oder Großeltern, erzählen eine Gutenacht-Geschichte oder moderieren eine Nachrichtensendung. Am Ende wird die Aufnahme zusammen angehört. Das schult Sprechen, Zuhören und Selbstvertrauen.', (select id from categories where content_type = 'micro_adventure' and slug = 'kreativ-entdecken'), 30, 60, 'free', 0.00, 'light', 'easy', true, false, array['fruehling', 'sommer', 'herbst', 'winter']::text[], array['regen', 'trocken']::text[], array['Smartphone mit Sprachmemo', 'Zettel für Fragen', 'ruhiger Raum']::text[], '1. Thema und kurze Fragen oder eine Geschichte vorbereiten.
2. Sprachmemo starten und in Ruhe sprechen lassen.
3. Aufnahme gemeinsam anhören und über die Lieblingsstellen sprechen.
4. Auf Wunsch einen Jingle oder Geräusche ergänzen.', 'Aufnahmen nur für die Familie behalten und nicht ohne Einverständnis aller Beteiligten im Internet veröffentlichen.', array['Gut an Regentagen', 'Stärkt Sprechfreude und Zuhören', 'Entstehende Aufnahmen werden zur Erinnerung']::text[], array['Schüchterne Kinder brauchen Zeit', 'Hintergrundgeräusche stören manchmal']::text[], true, 'draft', false),
  ('Lichtmalerei mit Taschenlampen', 'lichtmalerei', 'Im Dunkeln mit Lampen in die Luft malen und mit Langzeitbelichtung als Foto festhalten.', 'In einem abgedunkelten Raum oder am Abend im Garten malt ihr mit Taschenlampen, Knicklichtern oder Wunderkerzen-Alternativen Figuren in die Luft. Das Smartphone steht auf einem festen Untergrund und belichtet mit Nachtmodus oder einer Langzeitbelichtungs-Funktion mehrere Sekunden lang. So entstehen leuchtende Zeichnungen, die ihr im Anschluss anschauen könnt.', (select id from categories where content_type = 'micro_adventure' and slug = 'kreativ-entdecken'), 30, 60, 'free', 0.00, 'moderate', 'medium', true, true, array['herbst', 'winter', 'fruehling']::text[], array['dunkel', 'trocken']::text[], array['Smartphone mit Nachtmodus oder Langzeitbelichtung', 'Taschenlampen oder Knicklichter', 'festen Untergrund oder Stativ', 'dunkle Kleidung']::text[], '1. Kamera auf festen Untergrund stellen und Langzeitbelichtungs-Modus oder Nachtmodus aktivieren.
2. Raum abdunkeln, Kinder in dunkler Kleidung malen mit Lampen in die Luft.
3. Aufnahme auslösen, in Ruhe zeichnen und das Ergebnis betrachten.
4. Motive wechseln: Sterne, Namen, Tiere.', 'Im Dunkeln auf Hindernisse achten und nur ruhige Bewegungen machen. Keine offenen Flammen oder Wunderkerzen in Innenräumen verwenden.', array['Beeindruckende Ergebnisse mit einfachen Mitteln', 'Funktioniert drinnen wie draußen', 'Gut für mehrere Kinder abwechselnd']::text[], array['Ergebnis hängt vom Smartphone ab', 'Etwas Ausprobieren nötig']::text[], true, 'draft', false),
  ('Regenmesser bauen und Wetter-Tagebuch', 'regenmesser-wetter-tagebuch', 'Aus einer Plastikflasche einen Regenmesser bauen und eine Woche lang Wetterdaten sammeln.', 'Eine durchsichtige Plastikflasche wird oben abgeschnitten, umgedreht als Trichter eingesetzt und mit einer Skala aus Millimetern beklebt. Draußen aufgestellt, sammelt sie Regenwasser. Die Kinder tragen täglich Niederschlag, Temperatur und Wolkenbild in ein Wetter-Tagebuch ein. Ein Millimeter Niederschlag entspricht dabei einem Liter pro Quadratmeter.', (select id from categories where content_type = 'micro_adventure' and slug = 'kreativ-entdecken'), 30, 60, 'free', 0.00, 'moderate', 'easy', false, true, array['fruehling', 'sommer', 'herbst', 'winter']::text[], array['regen', 'bewoelkt']::text[], array['leere Plastikflasche', 'Schere oder Cuttermesser (nur Erwachsene)', 'Lineal und Klebeband', 'Notizbuch']::text[], '1. Flasche oben abschneiden und den Oberteil als Trichter umgedreht einsetzen.
2. Eine Millimeterskala von unten aufkleben und die Flasche sicher draußen aufstellen.
3. Täglich zur gleichen Zeit die Menge ablesen und Wetter ins Tagebuch eintragen.
4. Nach einer Woche gemeinsam auswerten, was am meisten Regen gebracht hat.', 'Schneiden der Flasche nur durch Erwachsene. Behälter standsicher platzieren, damit er nicht umkippt oder Tiere anlockt.', array['Lernprojekt über mehrere Tage', 'Gut für Regenwetter und Wetterbegeisterte', 'Material meist vorhanden']::text[], array['Ergebnis zeigt sich erst über einige Tage', 'Bei Frost kann der Behälter einfrieren']::text[], true, 'draft', false),
  ('Wolken-Detektive', 'wolken-detektive', 'Auf einer Decke liegen, Wolkenformen deuten und dazu Geschichten erfinden.', 'Ihr legt euch auf eine Decke ins Gras und schaut gemeinsam in den Himmel. Jede Wolke bekommt einen Namen: Drache, Schaf, Burg. Ihr erfindet Geschichten dazu, schaut, wie sich die Formen verändern, und lernt nebenbei einfache Wolkenarten wie Haufenwolken (Cumulus) und Schleierwolken (Cirrus) kennen. Perfekt als ruhige Pause nach einem aktiven Tag.', (select id from categories where content_type = 'micro_adventure' and slug = 'natur-wald'), 20, 45, 'free', 0.00, 'none', 'easy', false, true, array['fruehling', 'sommer', 'herbst']::text[], array['trocken', 'bewoelkt']::text[], array['Decke', 'Wolkenkarte oder Bestimmungs-App (optional)']::text[], '1. Eine trockene Wiese oder einen Park auswählen und eine Decke ausbreiten.
2. Auf den Rücken legen und eine Minute still schauen.
3. Reihum eine Wolke aussuchen, benennen und eine kurze Geschichte erfinden.
4. Nach zehn Minuten schauen, wie sich die Wolken verändert haben.', 'Nicht in die Sonne schauen. Bei Gewitterwolken oder aufziehendem Sturm sofort den Platz verlassen. Sonnenschutz und Trinkwasser mitnehmen.', array['Entspannt und kostet nichts', 'Fördert Fantasie und Erzählfreude', 'Ideal als Pause bei langen Ausflügen']::text[], array['Bei komplett bedecktem oder wolkenlosem Himmel weniger spannend', 'Wenig Bewegung, für Bewegungsfreudige als Ergänzung gedacht']::text[], true, 'draft', false)
